import { RunResult, TestCaseResult } from "../results/test_result.js";
import { RunData, RunOptions } from "./test_suite.js";
import { ItFn, ItOptions } from "../runner/test_api.js";
import { BeforeAfter } from "./before_after.js";

export class Runnable {

	private readonly _name: string[];
	private readonly _options: ItOptions;
	private readonly _fnAsync?: ItFn;
	private _filename?: string;

	static create(name: string[], options: ItOptions, fnAsync?: ItFn) {
		return new Runnable(name, options, fnAsync);
	}

	constructor(name: string[], options: ItOptions, fnAsync?: ItFn) {
		this._name = name;
		this._options = options;
		this._fnAsync = fnAsync;
	}

	/** @private */
	_setFilename(filename: string) {
		if (this._filename === undefined) this._filename = filename;
	}

	get name(): string[] {
		return this._name;
	}

	get options(): ItOptions {
		return this._options;
	}

	get fnAsync(): ItFn | undefined {
		return this._fnAsync;
	}

	async runAsync(
		runOptions: RunOptions,
		runData: RunData,
	): Promise<RunResult> {
		const fnAsync = this._fnAsync;
		if (runData.skipAll || fnAsync === undefined) {
			return RunResult.skip({
				name: this._name,
				filename: this._filename
			});
		}

		const timeout = this._options.timeout ?? runData.timeout;
		return await runOptions.clock.timeoutAsync(timeout, async () => {
			try {
				await fnAsync({ getConfig });
				return RunResult.pass({
					name: this._name,
					filename: this._filename
				});
			}
			catch (error) {
				return RunResult.fail({
					name: this._name,
					filename: this._filename,
					error,
					renderError: runOptions.renderError
				});
			}
		}, async () => {
			return await RunResult.timeout({
				name: this._name,
				filename: this._filename,
				timeout: runData.timeout
			});
		});

		function getConfig<T>(name: string) {
			if (runOptions.config[name] === undefined) throw new Error(`No test config found for name '${name}'`);
			return runOptions.config[name] as T;
		}
	}

}


// Use this class to make sure a runnable always passes even if it would normally be skipped
export class AlwaysPassRunnable extends Runnable {

	private _subclassFilename?: string;

	constructor(name: string[]) {
		super(name, {});
	}

	override _setFilename(filename: string) {
		if (this._subclassFilename === undefined) this._subclassFilename = filename;
	}

	override async runAsync(
		runOptions: RunOptions,
		runData: RunData,
	): Promise<RunResult> {
		return await RunResult.pass({
			name: this.name,
			filename: this._subclassFilename,
		});
	}

}
